package hms.core.m1.rsc.dataloader.service.reportGenerator

import hms.common.snmp.log.utils.manager.CommonSNMPManager
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.jdbc.core.SqlParameter
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource
import org.springframework.jdbc.core.simple.SimpleJdbcCall
import org.springframework.stereotype.Component
import java.sql.SQLException
import java.sql.Types
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.util.*


@Component
class ReportGeneratorRepository(val commonSNMPManager: CommonSNMPManager, val jdbcTemplate: JdbcTemplate, @Value("\${snmp.delay}") private val snmpTimeoutSeconds: Int,) {
    companion object {
        private val LOGGER = LoggerFactory.getLogger(ReportGeneratorRepository::class.java)
        private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
        const val RSC_DL_ERROR_SNMP_KEY = "rsc.dl.err"
        const val RSC_RPT_ERROR_SNMP_KEY = "rsc.dl.rpt.db"
    }

    @Value("\${snmp.snmp-trap-messages.db-connectivity.message}")
    private val dbConnectMessage: String? = null
    @Value("\${snmp.snmp-trap-messages.db-errors.message}")
    private val dbErrorMessage: String? = null
    @Value("\${snmp.snmp-trap-messages.query-errors.message}")
    private val queryErrorMessage: String? = null

    fun getHourlyTpsUtilizationSummary(start_date: LocalDate, end_date: LocalDate): Map<String, Any> {
        try{
            val simpleJdbcCall = SimpleJdbcCall(jdbcTemplate)
                .withProcedureName("spStored_insert_hourly_tps_summary")
                .declareParameters(
                    SqlParameter("start_date", Types.DATE),
                    SqlParameter("end_date", Types.DATE)
                )

            return simpleJdbcCall.execute(
                MapSqlParameterSource("start_date", java.sql.Date.valueOf( start_date ))
                    .addValue("end_date", java.sql.Date.valueOf( end_date ))
            );

        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while checking whether report details are there for date ${start_date} and type TPS : $ex")
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
            return emptyMap()
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting report status for date ${start_date} and type TPS", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return emptyMap()
        }
    }

    fun getPartiallyUpdatedReportDetails(currentDate: LocalDate): List<ReportGeneratingInfo>{
        try{
            val partiallyUpdatedReports = jdbcTemplate.query(
                "SELECT *  FROM report_generating_info WHERE generated_date<=? AND status=?",
                {rs, n -> ReportGeneratingInfo(
                    rs.getString("file_name"),
                    LocalDate.parse(rs.getString("generated_date"), dateFormatter),
                    rs.getString("report_type"),
                    rs.getString("generated_file_path"),
                    ReportGeneratingStatus.valueOf(rs.getString("status"))
                )},
                currentDate, ReportGeneratingStatus.PARTIALLY.name
            )
            return partiallyUpdatedReports

        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while checking whether partially updated report details are there for date ${currentDate} : $ex")
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage
            )
            return emptyList()
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting partially updated report status for date ${currentDate} ", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return emptyList()
        }
    }

