            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage
            )
            return emptyList()
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting partially updated report status for date ${currentDate} ", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return emptyList()
        }
    }

    fun getTpsUtilizationSummaryForPartiallyUpdatedReports(lastUpdatedDate: LocalDate,
                                                           currentDate: LocalDate,
                                                           lastUpdatedHour: Int): List<TpsUtilizationSummary> {

        val calendar = Calendar.getInstance()
        val currentHour = calendar[Calendar.HOUR_OF_DAY]
        try{
            val tpsSummaryForHour = jdbcTemplate.query(
                "SELECT * FROM tps_utilization_summary WHERE tps_summary_date>=? AND" +
                        " tps_summary_date<=? AND" +
                        " tps_summary_hour>? AND" +
                        " tps_summary_hour<=?",
                {rs, n -> TpsUtilizationSummary(
                    rs.getInt("id"),
                    LocalDate.parse(rs.getString("tps_summary_date"), dateFormatter),
                    rs.getInt("tps_summary_hour"),
                    rs.getString("rsc_server_id"),
                    rs.getInt("total_request_count"),
                    rs.getInt("total_success_count"),
                    rs.getInt("total_error_count"),
                    rs.getInt("max_requests_per_second"),
                    rs.getInt("max_success_requests_per_second"),
                    rs.getInt("max_error_requests_per_second")
                )},
                lastUpdatedDate, currentDate, lastUpdatedHour, currentHour
            )
            return tpsSummaryForHour

        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while checking whether partially updated report details are there for date ${currentDate} and type TPS : $ex")
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
            return emptyList()
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting partially updated report status for date ${currentDate} and type TPS", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return emptyList()
        }
    }

    fun insertReportGenerationStatus(
        file_name: String,
        generated_date: LocalDate,
        report_type: ReportType,
        generated_file_path: String,
        status: ReportGeneratingStatus
    ) {
        try {
            val query = """
                INSERT INTO report_generating_info (file_name, generated_date, report_type, generated_file_path, status) 
                VALUES(?, ?, ?, ?, ?)
                ON DUPLICATE KEY UPDATE generated_date = ?, status = ?;
                """.trimIndent()
            jdbcTemplate.update(
                query,
                file_name,
                generated_date,
                report_type.name,
                generated_file_path,
                status.name,
                generated_date,
                status.name
            )
            commonSNMPManager.clearTrap("rsc.dl.rpt.db", "DB Connect successFully")
        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while insert to table report_generating_info in file [${file_name}]", ex)
            commonSNMPManager.timeTrap(RSC_RPT_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while insert to table report_generating_info in file [${file_name}]", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, 5, "Error occurred while getting query")
        }

    }

    fun updateReportGenerationStatus(
        file_name: String,
        generated_date: LocalDate,
        status: ReportGeneratingStatus
    ) {
        try {
            jdbcTemplate.execute(
                "UPDATE report_generating_info SET status='${status.name}' WHERE file_name='${file_name}' AND generated_date='${generated_date}'"
            )
            commonSNMPManager.clearTrap(RSC_RPT_ERROR_SNMP_KEY, dbConnectMessage)
        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while update report details for file [${file_name}]", ex)
            commonSNMPManager.timeTrap(RSC_RPT_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
        } catch (e: Exception) {
            LOGGER.error("Error occurred while update report details for file [${file_name}]", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
        }
    }

    fun markReportGenerationStatusAs(generatingInfo: ReportGeneratingInfo, status: ReportGeneratingStatus) {
        updateReportGenerationStatus(generatingInfo.file_name, generatingInfo.generated_date, status)
    }


    fun isReportGenerated(currentDate: LocalDate, report_type: ReportType): ReportGeneratingStatus {
        try {
            //debug logs for information
            commonSNMPManager.clearTrap(RSC_RPT_ERROR_SNMP_KEY, dbConnectMessage)
            val generatedFileStatus = jdbcTemplate.query(
                "SELECT status  FROM report_generating_info WHERE generated_date=? AND report_type=?",
                { rs, n -> rs.getString("status").let { ReportGeneratingStatus.valueOf(it) }},
                currentDate, report_type.name
            )
            return generatedFileStatus.getOrElse(0) { ReportGeneratingStatus.NONE }
        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while checking whether report details are there for date ${currentDate} and type ${report_type} : $ex")
            commonSNMPManager.timeTrap(RSC_RPT_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
            return ReportGeneratingStatus.NONE
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting report status for date ${currentDate} and type ${report_type}", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return ReportGeneratingStatus.NONE
        }
    }


    fun getHourlyErrorSummary(start_date: LocalDate, end_date: LocalDate): Map<String, Any> {
        try{
            val simpleJdbcCall = SimpleJdbcCall(jdbcTemplate)
