    fun getErrorSummaryForPartiallyUpdatedReports(lastUpdatedDate: LocalDate,
                                                  currentDate: LocalDate,
                                                  lastUpdatedHour: Int): List<ErrorSummary> {

        val calendar = Calendar.getInstance()
        val currentHour = calendar[Calendar.HOUR_OF_DAY]
        try{
            val errorSummaryForHour = jdbcTemplate.query(
                "SELECT * FROM error_summary WHERE error_summary_date>=? AND" +
                        " error_summary_date<=? AND" +
                        " error_summary_hour>? AND" +
                        " error_summary_hour<=?",
                {rs, n -> ErrorSummary(
                    rs.getInt("id"),
                    LocalDate.parse(rs.getString("error_summary_date"), dateFormatter),
                    rs.getInt("error_summary_hour"),
                    rs.getString("rsc_server_id"),
                    rs.getString("error_code"),
                    rs.getInt("error_count")
                )},
                lastUpdatedDate, currentDate, lastUpdatedHour, currentHour
            )
            return errorSummaryForHour

        } catch (ex: SQLException) {
            LOGGER.error("DB Exception thrown while checking whether partially updated error report details are there for date ${currentDate}: $ex")
            commonSNMPManager.timeTrap(RSC_RPT_ERROR_SNMP_KEY, snmpTimeoutSeconds, dbErrorMessage)
            return emptyList()
        } catch (e: Exception) {
            LOGGER.error("Error occurred while getting partially updated error report status for date ${currentDate}", e)
            commonSNMPManager.timeTrap(RSC_DL_ERROR_SNMP_KEY, snmpTimeoutSeconds, queryErrorMessage)
            return emptyList()
        }
    }

    fun getErrorSummaryPercentageForHour(date: LocalDate, hour: Int, errorCode: String): Double {
        val startTime: LocalDateTime  = LocalDateTime.of(date.year, date.monthValue, date.dayOfMonth, hour, 0)
        val endTime: LocalDateTime = resolveEndTimeForErrorSummary(hour, date)

        var errorPercentage: Double = 0.0;
        val errorCount = getErrorCountForErrorSummary(startTime, endTime, errorCode)
        val totalTransactionsCount = getTotalTransactionsCountForErrorSummary(startTime, endTime)

        if(errorCount[0] > 0) {
            errorPercentage = (errorCount[0].toDouble()/totalTransactionsCount[0].toDouble()) * 100
        }

        val filterUserPrice: String = "%.2f".format(errorPercentage)
        return filterUserPrice.toDouble()

    }

    private fun getErrorCountForErrorSummary(
        startTime: LocalDateTime,
        endTime: LocalDateTime,
        errorCode: String
    ): MutableList<Int> = jdbcTemplate.query(
        "SELECT COUNT(*) AS error_count" +
                " FROM trans_log where log_time >=? AND log_time <? AND status_code =?",
        { rs, n -> rs.getInt("error_count") },
        startTime, endTime, errorCode
    )

    private fun getTotalTransactionsCountForErrorSummary(
        startTime: LocalDateTime,
        endTime: LocalDateTime
    ): MutableList<Int> = jdbcTemplate.query(
        "SELECT COUNT(*) AS total_count" +
                " FROM trans_log where log_time >=? AND log_time <?",
        { rs, n -> rs.getInt("total_count") },
        startTime, endTime
    )

    private fun resolveEndTimeForErrorSummary(
        hour: Int,
        date: LocalDate
    ): LocalDateTime {
        var endTime1: LocalDateTime
        if (hour + 1 > 23) {
            endTime1 = LocalDateTime.of(date.year, date.monthValue, date.dayOfMonth, 0, 0)
            endTime1 = endTime1.plusDays(1)
        } else {
            endTime1 = LocalDateTime.of(date.year, date.monthValue, date.dayOfMonth, hour + 1, 0)
        }
        return endTime1
    }

