@Component
class ReportGeneratorService(
    @Value("\${reporting.reportPath}") val reportPath: String,
    @Value("\${reporting.tpsUtilizationSummaryReportName}") val tpsUtilizationSummaryReportName: String,
    @Value("\${reporting.errorSummaryReportName}") val errorSummaryReportName: String,
    @Value("\${reporting.transactionSummaryReportName}") val transactionSummaryReportName: String,

    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.Date}") val hourlyTpsUtilizationSummaryHeadersDate: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.Hours}") val hourlyTpsUtilizationSummaryHeadersHours: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.RSCServerId}") val hourlyTpsUtilizationSummaryHeadersRSCServerId: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.TotalRequestCount}") val hourlyTpsUtilizationSummaryHeadersTotalRequestCount: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.TotalSuccessCount}") val hourlyTpsUtilizationSummaryHeadersTotalSuccessCount: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.TotalFailedCount}") val hourlyTpsUtilizationSummaryHeadersTotalFailedCount: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.MaxRequestPerSecond}") val hourlyTpsUtilizationSummaryHeadersMaxRequestPerSecond: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.MaxSuccessPerSecond}") val hourlyTpsUtilizationSummaryHeadersMaxSuccessPerSecond: String,
    @Value("\${reporting.hourlyTpsUtilizationSummaryHeaders.MaxFailPerSecond}") val hourlyTpsUtilizationSummaryHeadersMaxFailPerSecond: String,

    @Value("\${reporting.hourlyTransactionSummaryHeaders.Date}") val hourlyTransactionSummaryHeadersDate: String,
    @Value("\${reporting.hourlyTransactionSummaryHeaders.Hour}") val hourlyTransactionSummaryHeadersHour: String,
    @Value("\${reporting.hourlyTransactionSummaryHeaders.RequestCount}") val hourlyTransactionSummaryHeadersRequestCount: String,
    @Value("\${reporting.hourlyTransactionSummaryHeaders.SuccessCount}") val hourlyTransactionSummaryHeadersSuccessCount: String,
    @Value("\${reporting.hourlyTransactionSummaryHeaders.ErrorCount}") val hourlyTransactionSummaryHeadersErrorCount: String,
    @Value("\${reporting.hourlyTransactionSummaryHeaders.SuccessRate}") val hourlyTransactionSummaryHeadersSuccessRate: String,

    @Value("\${reporting.errorSummary.Date}") val errorSummaryDate: String,
    @Value("\${reporting.errorSummary.Hour}") val errorSummaryHour: String,
    @Value("\${reporting.errorSummary.RSCServerId}") val errorSummaryRSCServerId: String,
    @Value("\${reporting.errorSummary.ErrorCode}") val errorSummaryErrorCode: String,
    @Value("\${reporting.errorSummary.ErrorCount}") val errorSummaryErrorCount: String,
    @Value("\${reporting.errorSummary.ErrorPercentage}") val errorSummaryErrorPercentage: String,

    val distributedTemplateLockManager: DistributedTemplateLockManager,
    val reportGeneratorRepository: ReportGeneratorRepository
) {
    companion object {
        private val LOGGER = LoggerFactory.getLogger(ReportGeneratorService::class.java)
        private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    }

    fun handleSummaryReportGeneration(currentDate: LocalDate) {
        try {
            val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
            val timeThreshold = LocalDateTime.of(currentDate, LocalTime.of(0, 30))
            val timeThresholdForDayOldReports = LocalDateTime.of(currentDate.minusDays(1), LocalTime.of(0, 30))
            LOGGER.info("Start running summary generation timeThresholdForDayOldReports[$timeThresholdForDayOldReports]")
            generateTransLogSummaryReports(dateFormatter, timeThresholdForDayOldReports, timeThreshold, currentDate)
            generateTpsLogSummaryReports(dateFormatter, timeThresholdForDayOldReports, timeThreshold, currentDate)
            LOGGER.info("Finished running summary generation timeThresholdForDayOldReports[$timeThresholdForDayOldReports]")
        } catch (ex: Exception) {
            LOGGER.error("Unexpected error while generating summary reports", ex)
        }
    }

    private fun generateTpsLogSummaryReports(
        dateFormatter: DateTimeFormatter?,
        timeThresholdForDayOldReports: LocalDateTime?,
        timeThreshold: LocalDateTime?,
        currentDate: LocalDate
    ) {
        try {
            MDC.put("logType", "TPS_SUMMARY")
            val lastInsertedTPSLogTimeAsString = reportGeneratorRepository.getLastInsertedTPSLogTime()
            val lastInsertedTPSLogTime = LocalDateTime.parse(lastInsertedTPSLogTimeAsString, dateFormatter)
            LOGGER.debug("Generating TPS Summary report timeThresholdForDayOldReports[${timeThresholdForDayOldReports}] timeThreshold[${timeThreshold}] currentDate[${currentDate}] lastInsertedTransLogTime[${lastInsertedTPSLogTime}]")

            if (lastInsertedTPSLogTime > timeThresholdForDayOldReports) {
                var yesterday = currentDate.minusDays(1)
                val yesterdayTpsReportStatus = reportGeneratorRepository.isReportGenerated(yesterday, ReportType.TPS)
                if (yesterdayTpsReportStatus != ReportGeneratingStatus.GENERATED) {
                    handleTpsUtilizationSummaryReport(yesterday, yesterdayTpsReportStatus)
                    val tpsUtilizationSummaryFileName = "$tpsUtilizationSummaryReportName-$yesterday.csv"
                    markReportStatusAsGenerated(tpsUtilizationSummaryFileName, yesterday)
                }

                val todayReportStatus =
                    reportGeneratorRepository.isReportGenerated(lastInsertedTPSLogTime.toLocalDate(), ReportType.TPS)
                handleTpsUtilizationSummaryReport(lastInsertedTPSLogTime.toLocalDate(), todayReportStatus)

            } else {
                LOGGER.debug("Not generating TPS log summary generating because lastInsertedTransLogTime[$lastInsertedTPSLogTime] > timeThresholdForDayOldReports[$timeThresholdForDayOldReports]")

            }
        } catch (th: Throwable) {
            LOGGER.error("Unexpected error while processing [TPS_SUMMARY]", th)
        } finally {
            MDC.clear()
        }
    }

    private fun generateTransLogSummaryReports(
        dateFormatter: DateTimeFormatter?,
        timeThresholdForDayOldReports: LocalDateTime?,
        timeThreshold: LocalDateTime?,
        currentDate: LocalDate
    ) {
        try {
            MDC.put("logType", "TRANS_SUMMARY")
            val lastInsertedTransLogTimeAsString = reportGeneratorRepository.getLastInsertedTransLogTime()
            val lastInsertedTransLogTime = LocalDateTime.parse(lastInsertedTransLogTimeAsString, dateFormatter)

            LOGGER.debug("Generating TransLog Summary report timeThresholdForDayOldReports[${timeThresholdForDayOldReports}] timeThreshold[${timeThreshold}] currentDate[${currentDate}] lastInsertedTransLogTime[${lastInsertedTransLogTime}]")

            if (lastInsertedTransLogTime > timeThresholdForDayOldReports) {
                val yesterday = currentDate.minusDays(1)

                val yesterdayErrorReportStatus =
                    reportGeneratorRepository.isReportGenerated(yesterday, ReportType.ERROR)
                if (yesterdayErrorReportStatus != ReportGeneratingStatus.GENERATED) {
                    handleErrorSummaryReport(yesterday, yesterdayErrorReportStatus)
                    val errorSummaryFileName = "$errorSummaryReportName-${yesterday}.csv"
                    markReportStatusAsGenerated(errorSummaryFileName, yesterday)
                }

                val yesterdayTransReportStatus =
                    reportGeneratorRepository.isReportGenerated(yesterday, ReportType.TRANSACTION)
                if (yesterdayTransReportStatus != ReportGeneratingStatus.GENERATED) {
                    handleTransactionSummaryReport(yesterday, yesterdayTransReportStatus)
                    val transactionSummaryFileName = "$transactionSummaryReportName-${yesterday}.csv"
                    markReportStatusAsGenerated(transactionSummaryFileName, currentDate.minusDays(1))
                }

                val todayErrorReportStatus = reportGeneratorRepository.isReportGenerated(currentDate, ReportType.ERROR)
                handleErrorSummaryReport(currentDate, todayErrorReportStatus)

                val todayTransReportStatus =
                    reportGeneratorRepository.isReportGenerated(currentDate, ReportType.TRANSACTION)
                handleTransactionSummaryReport(currentDate, todayTransReportStatus)

            } else {
                LOGGER.debug("Not generating trans log summary because lastInsertedTransLogTime[$lastInsertedTransLogTime] > timeThresholdForDayOldReports[$timeThresholdForDayOldReports]")
            }
        } catch (th: Throwable) {
            LOGGER.error("Unexpected error while processing [TRANS_SUMMARY]", th)
        } finally {
            MDC.clear()
        }
