    fun handlePartiallyUpdatedSummaryReports(currentDate: LocalDate) {
        val dft = DateTimeFormatter.ofPattern("yyyy-MM-dd hh:mm:ss")
        LOGGER.info("Started recovering partially updated summary reports. Started Time ${dft.format(LocalDateTime.now())}")
        val partiallyUpdatedReportDetails = reportGeneratorRepository.getPartiallyUpdatedReportDetails(currentDate)
        if (partiallyUpdatedReportDetails.isNotEmpty()) {
            val partiallyUpdatedTpsReportDetails = partiallyUpdatedReportDetails
                .filter { t -> ReportType.valueOf(t.report_type) == ReportType.TPS }
            val partiallyUpdatedErrorReportDetails = partiallyUpdatedReportDetails
                .filter { t -> ReportType.valueOf(t.report_type) == ReportType.ERROR }
            val partiallyUpdatedTransactionReportDetails = partiallyUpdatedReportDetails
                .filter { t -> ReportType.valueOf(t.report_type) == ReportType.TRANSACTION }
            if (partiallyUpdatedTpsReportDetails.isNotEmpty()) {
                updatePartiallyUpdatedTpsReport(partiallyUpdatedTpsReportDetails)
            }
            if (partiallyUpdatedErrorReportDetails.isNotEmpty()) {
                updatePartiallyUpdatedErrorReport(partiallyUpdatedErrorReportDetails)
            }
            if (partiallyUpdatedTransactionReportDetails.isNotEmpty()) {
                updatePartiallyUpdatedTransactionReport(partiallyUpdatedTransactionReportDetails)
            }
        }
        LOGGER.info("Completed recovering partially updated summary reports. Completed Time ${dft.format(LocalDateTime.now())}")
    }

    private fun updatePartiallyUpdatedTransactionReport(
        partiallyUpdatedTransactionReportDetails: List<ReportGeneratingInfo>
    ) {
        partiallyUpdatedTransactionReportDetails.forEach { it ->
            val dateList = getDateList(it.generated_date)

            dateList.forEach { s ->
                val generatedDate = dateFormatter.format(s)
                val fileName = "$transactionSummaryReportName-$generatedDate.csv"
                try {
                    MDC.put("logType", "TRANS_SUMMARY")
                    MDC.put("fileName", fileName)
                    LOGGER.info("Processing for partially created transaction report for date[$s]")
                    var reportDetails = reportGeneratorRepository.getReportDetails(s, ReportType.TRANSACTION.toString())
                    val res = reportGeneratorRepository.getHourlyTransactionSummary(s, s.plusDays(1))
                    if (reportDetails.isEmpty()) {
                        LOGGER.info("Existing report generation details not found")
                        generateNewTransactionSummaryReport(mapTransactionSummary(res, 1), fileName, s, true)
                    } else {
                        LOGGER.info("Existing report generation details found[$reportDetails]")
                        if (reportDetails.get(0).status == ReportGeneratingStatus.GENERATED) {
                            LOGGER.debug("Log is already fully generated [${reportDetails.get(0)}]")
                        } else {
                            generateNewTransactionSummaryReport(mapTransactionSummary(res, 1), fileName, s, true)
                            //Status is internationally update again since if there are no records generateNewTpsSummaryReport will
                            // not update the status
                            reportGeneratorRepository.markReportGenerationStatusAs(
                                reportDetails.get(0), ReportGeneratingStatus.GENERATED
                            )
                        }
                    }
                } catch (th: Throwable) {
                    LOGGER.error("Unexpected error while processing [$fileName]", th)
                } finally {
                    MDC.clear()
                }
            }
        }
    }

