    private fun getDateList(start_date: LocalDate): List<LocalDate> {
        var list = mutableListOf<LocalDate>()
        var date = start_date
        while (date < LocalDate.now()) {
            list.add(date)
            date = date.plusDays(1)
        }
        return list
