import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicInteger

interface TpsLogger {
    fun requestSuccessful()
    fun requestFailed()
}

@Component
class TpsLoggerImpl(
    @Value("\${spring.application.name}") private val serverId: String,
    private val alarmService: AlarmService
) : TpsLogger {
    companion object {
        @JvmStatic
        private val LOGGER = LoggerFactory.getLogger(TpsLoggerImpl::class.java)

        @JvmStatic
        private val TPS_LOGGER = LoggerFactory.getLogger("TPS_LOGGER")
    }

    private val successCounter: AtomicInteger = AtomicInteger(0)
    private val errorCounter: AtomicInteger = AtomicInteger(0)
    private val tpsPrintScheduler = Executors.newSingleThreadScheduledExecutor()

    init {
        tpsPrintScheduler.scheduleAtFixedRate({ printTpsLog() }, 1, 1, TimeUnit.SECONDS)
    }

    override fun requestSuccessful() {
        successCounter.incrementAndGet()
    }

    override fun requestFailed() {
        errorCounter.incrementAndGet()
    }

    private fun printTpsLog() {
        synchronized(this) {
            try {
                val success = successCounter.getAndSet(0)
                val error = errorCounter.getAndSet(0)
                alarmService.tpsThresholdAlarm((success + error).toDouble())
                TPS_LOGGER.info("SRV={}|S={}|E={}", serverId, success, error)
            } catch (ex: Throwable) {
                LOGGER.error("Error occurred while printing TPS log", ex)
            }
        }
    }
}

