interface TransLogger {
    fun printTransLog(context: Context, resp: WorkFlowStepResult)
}

@Component
class TransLoggerImpl(
    @Value("\${spring.application.name}") private val serverId: String,
    @Value("\${service-api.logs.translog.touch.interval.seconds}") private val logFileTouchIntervalSeconds: Long,
    private val tpsLogger: TpsLogger,
    private val alarmService: AlarmService
) : TransLogger, MinuteRollingLogger(logFileTouchIntervalSeconds) {

    /*
1. Transaction Id
2. Server: which handles the request
3. Date time
4. Time taken for transaction
5. Originated IP (The Operator IP)
6. Terminated IP (The RSC server IP)
7. Authentication status
8. MSISDN
9. IMSI
10. Request status code
11. Request status
12. Roaming status (True / False / Null for errors)
13. VLR address
14. Served from cache
15. Multi-SIM status
16. Child numbers in roaming
     */
    companion object {
        @JvmStatic
        private val LOG_TEMPLATE =
            "TRX_ID={}|SRV={}|REQ_TM={}|PRS_TM={}|O_IP={}|D_IP={}|AUTH={}|MSISDN={}|IMSI={}|STS={}|STS_DSC={}|RM_STS={}|VLR={}|FRM_CH={}|MUL_SIM={}|CHLD_NM={}"

        @JvmStatic
        private val TRANS_LOGGER = LoggerFactory.getLogger("TRANS_LOGGER")

        @JvmStatic
        private val DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy:MM:dd HH:mm:ss.SSS");
    }

    override fun touchLogger() {
        TRANS_LOGGER.info(INTENTIONALLY_EMPTY)
    }

    override fun printTransLog(context: Context, resp: WorkFlowStepResult) {
        val currentTimeMillis = System.currentTimeMillis()
        TRANS_LOGGER.info(
            LOG_TEMPLATE,
            context.traceId,
            serverId,
            context.receivedTime.format(DATE_FORMATTER),
            currentTimeMillis - context.receivedTimeMillis,
            context.remoteIp,
            context.hostIp,
            context.authenticated,
            context.msisdn,
            context.imsi,
            getRequestStatusCode(resp),
            getRequestStatusDescription(resp),
            context.roamingStatus,
            context.vlrAddress,
            context.servedFromCache,
            context.multiSim,
            context.childNumberRoaming.joinToString(",", "[", "]") { it.msisdn }
        )
        if(resp is WorkflowStepSuccess){
            tpsLogger.requestSuccessful()
        } else {
            tpsLogger.requestFailed()
        }
        alarmService.incrementConsecutiveTimeExceedCount(context, currentTimeMillis)
    }

}

