    val partialReportGeneratingSchedulerInitialDelay: Long,
    @Value("\${reporting.runSummaryCsvGeneration}")
    val runSummaryCsvGeneration: Boolean,
    val logProcessingInfoRepository: LogProcessingInfoRepository,
    val reportGeneratorRepository: ReportGeneratorRepository,
    val reportGeneratorService: ReportGeneratorService,
    val loadInFileProcessor: LoadInFileProcessor,
    val commonSNMPManager: CommonSNMPManager
) {

    companion object {
        private val LOGGER = LoggerFactory.getLogger(ServiceStarter::class.java)
    }

    private lateinit var fileLoadingScheduler: ScheduledExecutorService
    private lateinit var reportGeneratingScheduler: ScheduledExecutorService
    private lateinit var partialReportGeneratingScheduler: ScheduledExecutorService

    @PostConstruct
    fun start() {
        val columnTransformerAdapterFactory = RuntimeTypeAdapterFactory.of(ColumnTransformer::class.java, "type")
            .registerSubtype(NullColumnTransformer::class.java, "NullColumn")
            .registerSubtype(FieldWithColumnNameTransformer::class.java, "FieldWithColumnName")
            .registerSubtype(BooleanFieldTransformer::class.java, "BooleanField")

        val gson = GsonBuilder().registerTypeAdapterFactory(columnTransformerAdapterFactory).create()
        getLogSpecFiles(gson)

        try {
            startLogFileLoadingSchedulers()

            startSummaryCsvGenerationSchedulers()

        } catch (se: SQLException) {
            LOGGER.error("DB Exception thrown while loading.", se)
            commonSNMPManager.timeTrap("rsc.dl.rpt.db", snmpDelay, "DB Exception thrown while Load in files")
        } catch (e: Exception) {
            LOGGER.error("Error occurred while loading", e)
            commonSNMPManager.timeTrap("rsc.dl.err", snmpDelay, "Error occurred while loading")
        }
    }

    private fun startLogFileLoadingSchedulers() {
        fileLoadingScheduler =
            Executors.newSingleThreadScheduledExecutor(CustomizableThreadFactory("load_in_file_scheduler-"))
        val runner = Runnable {
            loadInFileProcessor.loadData()
        }
        fileLoadingScheduler.scheduleAtFixedRate(
            runner, 10, loadInFileSchedulerFrequencyInSeconds, TimeUnit.SECONDS
        )
        LOGGER.info("Log file loading schedulers started.")
    }

    private fun startSummaryCsvGenerationSchedulers() {
        if (runSummaryCsvGeneration) {
            reportGeneratingScheduler =
                Executors.newSingleThreadScheduledExecutor(CustomizableThreadFactory("report_generate_scheduler-"))
            partialReportGeneratingScheduler =
                Executors.newSingleThreadScheduledExecutor(CustomizableThreadFactory("partial_report_generate_scheduler-"))
            val reportGenerateRunner = Runnable {
                reportGeneratorService.handleSummaryReportGeneration(LocalDate.now())
            }

            val partialReportGenerateRunner = Runnable {
                reportGeneratorService.handlePartiallyUpdatedSummaryReports(LocalDate.now().minusDays(1))
            }
            reportGeneratingScheduler.scheduleAtFixedRate(
                reportGenerateRunner,
                reportingSchedulerInitialDelay,
                appendReportSchedulerFrequencyInSeconds,
                TimeUnit.SECONDS
            )
            partialReportGeneratingScheduler.schedule(
                partialReportGenerateRunner, partialReportGeneratingSchedulerInitialDelay, TimeUnit.MINUTES
            )
            LOGGER.info("Summary CSV generation schedulers started.")
        } else {
            LOGGER.info("Summary CSV generation is disabled in this server.")
        }
    }


    fun getLogSpecFiles(gson: Gson) {
        try {
            LOGGER.debug("getLogSpecFiles gson [${gson}]")
            val simpleDateFormat = SimpleDateFormat("yyyy-MM-dd hh:mm:ss")
            val specFilesPath = configPath
            val specFiles: Array<File>? = File(specFilesPath).listFiles()
            if (specFiles != null) {
                for (file in specFiles) {
                    val specFileName = specFilesPath.plus("/").plus(file.name)
                    val logProcessorConfig = getLogSpec(gson, specFileName)
                    val executor = Executors.newSingleThreadScheduledExecutor(
                        CustomizableThreadFactory("log-proc-${logProcessorConfig.logConfig.logName}-")
                    )
                    val runner = Runnable {
                        try {
                            LOGGER.info(
                                "Processing ${logProcessorConfig.logConfig.logName} start : ${
                                    simpleDateFormat.format(
                                        Date()
                                    )
                                }"
                            )
                            TransLogProcessor(
                                logProcessorConfig.logConfig,
                                logProcessorConfig.transLogSpec,
                                logProcessingInfoRepository,
                                commonSNMPManager,
                                snmpDelay
                            ).processLog()
                        } catch (e: Exception) {
                            LOGGER.error("Error occurred while processing in Runnable interface", e)
                            commonSNMPManager.timeTrap("rsc.dl.err", snmpDelay, "Error occurred while processing")
                        }
                    }
                    executor.scheduleWithFixedDelay(
                        runner, 10, logProcessorConfig.logConfig.schedulerIntervalInSeconds, TimeUnit.SECONDS
                    )

                }
            }
        } catch (e: SQLException) {
            LOGGER.error("Error occurred while processing  : ${e}")
            commonSNMPManager.timeTrap("rsc.dl.rpt.db", snmpDelay, "DB Exception thrown while processing files")
        } catch (e: java.lang.Exception) {
            LOGGER.error("Error occurred while processing : ${e}", e)
            commonSNMPManager.timeTrap("rsc.dl.err", snmpDelay, "Error occurred while processing")
        }
    }

    fun getLogSpec(gson: Gson, fileName: String): LogProcessorConfig {

        val parser = JsonParser()
        val jsontree = parser.parse(
            FileReader(fileName)
        )
        val je = jsontree.asJsonObject

        val logProcessorConfig: LogProcessorConfig = gson.fromJson(je, LogProcessorConfig::class.java)
        return logProcessorConfig
    }

}
